CustomField.formula:
/*First if completed same day*/
if( DateValue(Case_Reopened_Date__c)=DateValue(AgeEndpointDate_ReClosed__c),
/*Adjusts Closed Hour/Minute if it's before or after hours*/
if(AgeEndpointHour_ReClosed__c<8, 8, if(AgeEndpointHour_ReClosed__c>20, 20, AgeEndpointHour_ReClosed__c))+
if(AgeEndpointHour_ReClosed__c<8 || AgeEndpointHour_ReClosed__c>20, 0, Minute(TimeValue(AgeEndpointDate_ReClosed__c))/60)
-
/*Adjust Created Hour/Minute if it's before or after hours*/
(if(ReOpenedHour__c<8, 8, if(ReOpenedHour__c>20, 20, ReOpenedHour__c))+
if(ReOpenedHour__c<8 || ReOpenedHour__c>20, 0, Minute(TimeValue(Case_Reopened_Date__c)))/60),



/*If not the same day, calcs hours of first day, if after hours or weekend rounds Created down and Completed up*/
if( Weekday(DateValue(Case_Reopened_Date__c))=7 || Weekday(DateValue(Case_Reopened_Date__c))=0 || ReOpenedHour__c>=20, 0,
/*If it's before hours, limit to 8 hours*/
if(ReOpenedHour__c<8, 8, 20-(ReOpenedHour__c))+
if(ReOpenedHour__c<8 || ReOpenedHour__c>20, 0, (Minute(TimeValue(Case_Reopened_Date__c))/60))
)
+
/*Calcs days between and converts to hours by multiplying by 8 workhours*/
(CASE( WEEKDAY(DateValue(Case_Reopened_Date__c)),
/*This excludes End Dates e.g. Mon Tuesday Wednesday = 1*/
1 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
2 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
3 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
4 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
5 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
6 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
7 , CASE( MOD( DateValue(AgeEndpointDate_ReClosed__c)-DateValue(Case_Reopened_Date__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
999)
+
(FLOOR(( DateValue(AgeEndpointDate_ReClosed__c) - DateValue(Case_Reopened_Date__c) )/7)*5))*8
+
/*Calcs days at the end*/
/*If it's before hours, limit to 8 hours*/
if(AgeEndpointHour_ReClosed__c<8, 0, if(AgeEndpointHour_ReClosed__c>20, 20, AgeEndpointHour_ReClosed__c-8))+
if(AgeEndpointHour_ReClosed__c<8 || AgeEndpointHour_ReClosed__c>20, 0, (Minute(TimeValue(AgeEndpointDate_ReClosed__c))/60))

)-Dev_Hold_Hours__c - Workday_Hours_in_3rd_Party_ApprovalN__c
